// ApplyTagWeights applies ONE learning pass atomically (recommendation-
// sorting D5): every tag in tags gains +1 weight — one increment per
// element, so the caller's per-watch resolution (a tag shared by two watched
// rows is passed twice) accumulates exactly — and every still-unapplied
// watched row completed at or before appliedUpTo is stamped applied_at.
// Tags arrive normalized (trim + Unicode casefold, the tag rule; the store
// stays value-agnostic — ERROR-FLOOR LAW, doc.go # Invariants). The stamp's
// WHERE predicate
// is the caller's seen-batch cutoff, so a watch landing between the queue
// read and this call stays unapplied for the next pass (restart-safe). An
// empty tags slice stamps only — a watch whose entity resolved no tags is
// consumed without touching a weight (honest absence). Weights start at 1
// on first sight (interest 0 + 1, the D2 weight formula). One transaction:
// weights and stamps commit together or not at all.
func (s *Store) ApplyTagWeights(ctx context.Context, tags []string, appliedUpTo time.Time) error {
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return fmt.Errorf("store: apply tag weights (begin): %w", err)
	}
	defer func() { _ = tx.Rollback() }()
	upsert, err := tx.PrepareContext(ctx, `
INSERT INTO tag_weights (tag, weight, updated_at)
VALUES (?, 1, ?)
ON CONFLICT(tag) DO UPDATE SET
  weight     = weight + 1,
  updated_at = excluded.updated_at`)
	if err != nil {
		return fmt.Errorf("store: apply tag weights (prepare): %w", err)
	}
	defer upsert.Close()
	now := formatTime(time.Now().UTC())
	for _, tag := range tags {
		if _, err := upsert.ExecContext(ctx, tag, now); err != nil {
			return fmt.Errorf("store: apply tag weight %s: %w", tag, err)
		}
	}
	if _, err := tx.ExecContext(ctx, `
UPDATE watched_items
SET applied_at = ?
WHERE applied_at IS NULL AND completed_at <= ?`,
		now, formatTime(appliedUpTo),
	); err != nil {
		return fmt.Errorf("store: apply tag weights (stamp): %w", err)
	}
	if err := tx.Commit(); err != nil {
		return fmt.Errorf("store: apply tag weights (commit): %w", err)
	}
	return nil
}

// ListTagWeights reads the learned affinity: every tag row as ALIGNED
